import sqlite3,json,collections
c=sqlite3.connect('analytics.db')
steps=['install','tutorial_complete','first_match','purchase']
users={u:p for u,p in c.execute('select user_id,platform from users where is_test=0')}
ev=collections.defaultdict(lambda:collections.defaultdict(list))
for u,n,t in c.execute('select user_id,name,ts from events'):
  if u in users and n in steps: ev[u][n].append(t)
funnel={p:dict.fromkeys(steps,0) for p in sorted(set(users.values()))}
for u,p in users.items():
  prev=None
  for s in steps:
    ok=[t for t in ev[u][s] if prev is None or t>=prev]
    if not ok: break
    prev=min(ok); funnel[p][s]+=1
conv={p:{s:round(f[s]/f[steps[i-1]],4) for i,s in enumerate(steps) if i} for p,f in funnel.items()}
big={p:min(cv,key=cv.get) for p,cv in conv.items()}
json.dump({'funnel':funnel,'biggest_drop':big,'conversion':conv},open('result.json','w'),indent=2)
print(open('result.json').read())
